void test_http_cache_incomplete_request_cancellation() {
    // Setup mock HTTP cache and transaction
    HTTPCache *cache = create_mock_http_cache();
    HTTPTransaction *transaction = create_mock_http_transaction();

    // Simulate a GET request with incomplete resource data
    HTTPCacheEntry *entry = create_truncated_cache_entry();
    http_cache_add_entry(cache, entry);

    // Initiate a regular request and queue another to the same transaction
    HTTPRequest *request1 = create_http_request("GET", "/resource");
    HTTPRequest *request2 = create_http_request("GET", "/resource");

    http_transaction_start(transaction, request1);
    http_transaction_queue_request(transaction, request2);

    // Verify the transaction starts correctly and data can be read from cache
    char buffer[1024];
    size_t bytes_read = http_transaction_read(transaction, buffer, sizeof(buffer));
    assert(bytes_read > 0);

    // Cancel the requests
    http_transaction_cancel(transaction, request1);
    http_transaction_cancel(transaction, request2);

    // Check the state of the cache
    int active_transactions = http_cache_get_active_transactions(cache);
    int operations_count = http_cache_get_operation_count(cache);

    assert(active_transactions == 0);
    assert(operations_count == 2);  // One for each request

    // Clean up
    http_transaction_remove(transaction);
    http_cache_destroy(cache);
}

